<?php

/**
 * SocialApp change: parity guard for over-limit paragraphs. The fixture was generated by running
 * this splitter (scripts/gen-splitter-fixture.php); section-split.test.ts checks the composer
 * preview against the same file, so the preview always shows what will be published.
 */

use App\Enums\Platform;
use App\Services\Posts\PostSplitter;

/**
 * @return array<string, array{0: list<string>, 1: Platform, 2: int, 3: list<string>}>
 */
function overlimitParityCases(): array
{
    $path = __DIR__.'/../../Fixtures/post-splitter-overlimit-parity.json';
    /** @var list<array{name: string, platform: string, limit: int, segments: list<string>, expected: list<string>}> $cases */
    $cases = json_decode((string) file_get_contents($path), true, flags: JSON_THROW_ON_ERROR);

    $out = [];
    foreach ($cases as $case) {
        $out[$case['name']] = [$case['segments'], Platform::from($case['platform']), $case['limit'], $case['expected']];
    }

    return $out;
}

test('server splits over-limit paragraphs exactly as the fixture says', function (array $segments, Platform $platform, int $limit, array $expected) {
    expect((new PostSplitter)->split($segments, $platform, true, $limit)->sections)->toBe($expected);
})->with(overlimitParityCases());
